// Agente Especialista em Containers - Inicialização
// Especialista em: Docker Swarm, Containers, Serviços, Logs, Recursos

const payload = $input.item.json.body || $input.item.json;

return [{
  json: {
    agent: {
      name: 'Agente Especialista em Containers',
      version: '2.0',
      specialization: ['Docker Swarm', 'Containers', 'Docker Services', 'Logs', 'Recursos', 'Rede Docker', 'Volumes'],
      role: 'Troubleshooting e resolução de problemas em containers Docker'
    },
    sessionId: payload.sessionId,
    timestamp: payload.timestamp,
    issues: payload.issues || [],
    context: payload.context || {},
    orchestratorDecision: payload.orchestratorDecision || {},
    mode: payload.mode || 'troubleshooting_and_resolution',
    status: 'analyzing'
  }
}];

// Agregar dados coletados para análise
const agentData = $('Inicializar Agente').item.json;
const apiHealth = $('Verificar Saúde API').item.json;
const metrics = $('Verificar Métricas').item.json;

const collectedData = {
  api: {
    status: apiHealth.statusCode,
    response: apiHealth.body || {},
    healthy: apiHealth.statusCode === 200
  },
  metrics: {
    available: metrics.statusCode === 200,
    data: metrics.body || ''
  },
  vps: {
    host: '167.235.76.26',
    user: 'root',
    dockerSwarm: true
  }
};

return [{
  json: {
    ...agentData,
    collectedData: collectedData,
    readyForAnalysis: true
  }
}];

