// Processar resposta do Claude.ai - Troubleshooting e Resolução
const agentData = $('Agregar Dados').item.json;
const llmResponse = $input.item.json;

// Extrair texto da resposta
let analysisText = '';
let responseBody = llmResponse.body || llmResponse;
if (typeof responseBody === 'string') {
  try {
    responseBody = JSON.parse(responseBody);
  } catch (e) {
    responseBody = { content: [{ type: 'text', text: responseBody }] };
  }
}

if (responseBody.content && Array.isArray(responseBody.content)) {
  const textContent = responseBody.content.find(c => c.type === 'text');
  analysisText = textContent ? textContent.text : JSON.stringify(responseBody.content);
} else {
  analysisText = JSON.stringify(responseBody);
}

// Parsear JSON da resposta
let troubleshooting = {};
let resolution = {};
let hasIssues = agentData.issues.length > 0;

try {
  const jsonMatch = analysisText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    troubleshooting = parsed.troubleshooting || {};
    resolution = parsed.resolution || {};
  } else {
    // Fallback se não conseguir parsear
    troubleshooting = {
      diagnosis: {
        summary: analysisText.substring(0, 500),
        rootCause: 'A ser determinado',
        impact: 'Médio'
      },
      actionPlan: [],
      requiresApproval: false
    };
    resolution = {
      validation: { safeToExecute: false, error: 'Não foi possível parsear resposta' },
      executionPlan: [],
      requiresApproval: true
    };
  }
} catch (e) {
  troubleshooting = {
    diagnosis: {
      summary: analysisText,
      error: 'Erro ao parsear resposta'
    },
    actionPlan: [],
    requiresApproval: false
  };
  resolution = {
    validation: { safeToExecute: false, error: e.message },
    executionPlan: [],
    requiresApproval: true
  };
}

return [{
  json: {
    agent: agentData.agent,
    sessionId: agentData.sessionId,
    timestamp: new Date().toISOString(),
    issues: agentData.issues,
    troubleshooting: troubleshooting,
    resolution: resolution,
    hasIssues: hasIssues,
    rawAnalysis: analysisText.substring(0, 2000)
  }
}];
